let swap a i j = let t = a.(i) in a.(i) <- a.(j); a.(j) <- t

let insertion_sort a =
  for i = 1 to Array.length a - 1 do
    (* invariant: a.(0..i-1) is sorted *)
    let j = ref i in
    while !j > 0 && a.(!j - 1) > a.(!j) do
      swap a !j (!j - 1);
      decr j
    done
  done

let binary_search a x =
  let lo = ref 0 and hi = ref (Array.length a - 1) and found = ref (-1) in
  while !found < 0 && !lo <= !hi do
    let mid = (!lo + !hi) / 2 in
    if a.(mid) = x then found := mid
    else if a.(mid) < x then lo := mid + 1
    else hi := mid - 1
  done;
  !found

