let reverse_in_place a =
  let n = Array.length a in
  for i = 0 to n / 2 - 1 do
    let t = a.(i) in
    a.(i) <- a.(n - 1 - i);
    a.(n - 1 - i) <- t
  done

let () =
  let a = [| 1; 2; 3; 4 |] in
  reverse_in_place a;
  Array.iter (Printf.printf "%d ") a;
  print_newline ()

