  (match pop q1 with
   | Some (x, q2) ->
     Printf.printf "%d\n" x;
     (match pop q2 with Some (y, _) -> Printf.printf "%d\n" y | None -> ());
     (match pop q1 with Some (z, _) -> Printf.printf "again %d\n" z | None -> ())
   | None -> ());
  let mq = Queue.create () in
  Queue.add 1 mq; Queue.add 2 mq;
  let first = Queue.take mq in
  Printf.printf "%d %d\n" first (Queue.length mq)

